struct MemoryPager {
    std::map<std::uint64_t,json> pages;
    std::uint64_t next=1,reads=0,writes=0;
    std::size_t budget=1800;
    Pager pager(){return {[this](std::uint64_t id){++reads;return pages.at(id);},[this](std::uint64_t id,const json& j){++writes;if(!pages.count(id))throw std::runtime_error("write missing page");if(j.dump().size()>budget)throw std::runtime_error("oversized page");pages[id]=j;},[this](const json& j){++writes;if(j.dump().size()>budget)throw std::runtime_error("oversized allocation");auto id=next++;pages[id]=j;return id;},[this](std::uint64_t id){if(pages.erase(id)!=1)throw std::runtime_error("double retire");},budget};}
};
void check(bool ok,const std::string& message){if(!ok)throw std::runtime_error(message);}
bool eq(const std::vector<Entry>& a,const std::vector<Entry>& b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(compare_keys(a[i].key,b[i].key)||a[i].id!=b[i].id||a[i].payload!=b[i].payload)return false;return true;}
void sorted(std::vector<Entry>& values){std::sort(values.begin(),values.end(),[](const Entry& a,const Entry& b){auto c=compare_keys(a.key,b.key);return c?c<0:a.id<b.id;});}
