    for(auto i:sequence){Entry e{json::array({i%19, std::string("公共前缀数据库索引-")+std::to_string(i%7)}),i+1,{{"value",i},{"text",std::string(i%23,'x')}}};index.insert(e);expected.push_back(e);if(expected.size()%43==0){auto v=index.verify();check(v.value("ok",false),method+" insert verify: "+v.dump());}}
    sorted(expected);check(eq(index.all(),expected),method+" exact full scan");check(index.verify().value("ok",false),method+" full verify");{auto next=index.cursor();Entry e;std::vector<Entry> rows;while(next(e))rows.push_back(e);if(!capabilities(method).value("ordered",false))sorted(rows);check(eq(rows,expected),method+" streaming cursor exact model");}
    for(unsigned k=0;k<19;++k){Key key=json::array({k,"公共前缀数据库索引-3"});std::vector<Entry> matches;for(const auto& e:expected)if(!compare_keys(e.key,key))matches.push_back(e);check(eq(index.find(key),matches),method+" exact equality");auto next=index.cursor(key,key);Entry e;std::vector<Entry> streamed;while(next(e))streamed.push_back(e);sorted(streamed);check(eq(streamed,matches),method+" point cursor exact model");for(const auto& e:matches){auto page=index.locate(e.key,e.id);check(page.has_value(),method+" locate exact entry");if(method!="BITMAP"&&opts.value("dup_layout",std::string())!="posting"){auto direct=index.read_at(*page,e.key,e.id);check(direct&&direct->payload==e.payload,method+" direct physical read");check(!index.read_at(*page,json::array({"wrong"}),e.id),method+" direct read rejects wrong key");}}}
    auto low=json::array({4}),high=json::array({12});std::vector<Entry> range;for(const auto& e:expected)if(compare_keys(e.key,low)>=0&&compare_keys(e.key,high)<0)range.push_back(e);check(eq(index.range(low,high,true,false),range),method+" composite prefix range");
